    days_without_match = 0
    max_days = _MAX_YEARS * 366

    while True:
        if cron.matches_day(day):
            days_without_match = 0
            for h in hours:
                if first_day and h < current.hour:
                    continue
                for m in minutes:
                    if first_day and h == current.hour and m < current.minute:
                        continue
